[patterns/application/api-microservices/PTN-APP-API-008-domain-driven-design-pattern.md#phase-2-tactical-design---implement-domain-model-patterns]

#### Phase 2: Tactical Design - Implement Domain Model Patterns

**Step 4: Design Aggregates with Clear Boundaries**

Aggregates are clusters of domain objects (entities and value objects) that can be treated as a single unit for data changes. Each aggregate has a root entity that controls access to all objects in the aggregate.

**Aggregate Design Principles:**

1. **Keep Aggregates Small**: Only include entities that must be consistent within a single transaction
2. **Reference by Identity**: Aggregates reference other aggregates by ID, not direct object references
3. **Enforce Invariants**: Aggregate root enforces all business rules within the aggregate boundary
4. **Single Transaction**: All changes within an aggregate should succeed or fail together

**Real-World Example - Claims Aggregate Design:**

```csharp
// Claims Bounded Context - Domain Layer
namespace Gainwell.Claims.Domain.Aggregates
{
    // Aggregate Root - enforces invariants for entire aggregate
    public class Claim : AggregateRoot<ClaimId>
    {
        // Private fields - encapsulation
        private readonly List<ClaimLine> _claimLines = new();
        private readonly List<Adjustment> _adjustments = new();

        // Public properties - expose state
        public ClaimNumber ClaimNumber { get; private set; }
        public ProviderId ProviderId { get; private set; }
        public MemberId MemberId { get; private set; }
        public DateOfService ServiceDate { get; private set; }
        public ClaimStatus Status { get; private set; }
        public Money TotalBilledAmount { get; private set; }
        public Money TotalAllowedAmount { get; private set; }
        public Money TotalPaidAmount { get; private set; }

        // Read-only collection - external code cannot modify directly
        public IReadOnlyList<ClaimLine> ClaimLines => _claimLines.AsReadOnly();
        public IReadOnlyList<Adjustment> Adjustments => _adjustments.AsReadOnly();

        // Factory method - ensures valid Claim creation
        public static Claim Submit(
            ClaimNumber claimNumber,
            ProviderId providerId,
            MemberId memberId,
            DateOfService serviceDate,
            List<ClaimLineData> lineData)
        {
            // Validate invariants before creation
            if (lineData == null || !lineData.Any())
                throw new DomainException("Claim must have at least one service line");

            if (serviceDate.IsInFuture())
                throw new DomainException("Cannot submit claim for future service date");

            var claim = new Claim
            {
                Id = ClaimId.New(),
                ClaimNumber = claimNumber,
                ProviderId = providerId,
                MemberId = memberId,
                ServiceDate = serviceDate,
                Status = ClaimStatus.Submitted
            };

            // Add claim lines through aggregate root
            foreach (var data in lineData)
            {
                claim.AddClaimLine(
                    data.ServiceCode,
                    data.Units,
                    data.ChargedAmount,
                    data.DiagnosisCodes);
            }

            // Raise domain event
            claim.AddDomainEvent(new ClaimSubmittedEvent(
                claim.Id,
                claim.ClaimNumber,
                claim.ProviderId,
                claim.MemberId,
                claim.ServiceDate,
                claim.TotalBilledAmount));

            return claim;
        }

        // Business behavior - enforces invariants
        public void AddClaimLine(
            ServiceCode serviceCode,
            int units,
            Money chargedAmount,
            List<DiagnosisCode> diagnosisCodes)
        {
            // Invariant: No duplicate service codes on same date
            if (_claimLines.Any(l => l.ServiceCode == serviceCode))
                throw new DomainException(
                    $"Claim already contains service {serviceCode}");

            // Invariant: Total claim amount cannot exceed state limit
            var newTotal = TotalBilledAmount.Add(chargedAmount);
            if (newTotal.IsGreaterThan(Money.FromDollars(50000)))
                throw new DomainException(
                    "Total claim amount cannot exceed $50,000. " +
                    "Split into multiple claims.");

            // Invariant: At least one diagnosis code required
            if (!diagnosisCodes.Any())
                throw new DomainException(
                    "Claim line must have at least one diagnosis code");

            // Create claim line (internal constructor enforces aggregate boundary)
            var line = ClaimLine.Create(
                ClaimLineId.New(),
                this.Id, // Reference to parent aggregate
                serviceCode,
                units,
                chargedAmount,
                diagnosisCodes);

            _claimLines.Add(line);

            // Update aggregate state
            TotalBilledAmount = TotalBilledAmount.Add(chargedAmount);

            // Domain event for claim line added
            AddDomainEvent(new ClaimLineAddedEvent(Id, line.Id, serviceCode, chargedAmount));
        }

        // Business behavior - adjudication with invariants
        public AdjudicationResult Adjudicate(
            MemberEligibility eligibility,
            ProviderCredential credential,
            FeeSchedule pricing,
            PriorAuthorizationPolicy authPolicy)
        {
            // Can only adjudicate submitted or returned claims
            if (Status != ClaimStatus.Submitted && Status != ClaimStatus.Returned)
                throw new DomainException(
                    $"Cannot adjudicate claim in {Status} status");

            // Business Rule: Member must be eligible on service date
            if (!eligibility.IsActiveOn(ServiceDate))
            {
                Deny(DenialReason.MemberNotEligible,
                     "Member does not have active coverage on service date");
                return AdjudicationResult.Denied(DenialReason.MemberNotEligible);
            }

            // Business Rule: Provider must be credentialed
            if (!credential.IsValidOn(ServiceDate))
            {
                Deny(DenialReason.ProviderNotCredentialed,
                     "Provider credentials expired or suspended");
                return AdjudicationResult.Denied(DenialReason.ProviderNotCredentialed);
            }

            // Adjudicate each claim line
            var lineResults = new List<ClaimLineAdjudication>();
            foreach (var line in _claimLines)
            {
                // Check prior authorization
                if (authPolicy.RequiresAuthorization(line.ServiceCode))
                {
                    var auth = authPolicy.GetAuthorization(line.ServiceCode, ServiceDate);
                    if (auth == null || auth.IsExpired)
                    {
                        line.Deny(DenialReason.AuthorizationRequired);
                        continue;
                    }
                }

                // Apply pricing
                var allowedAmount = pricing.GetAllowedAmount(
                    line.ServiceCode,
                    line.Units,
                    credential.SpecialtyCode);

                line.Approve(allowedAmount);
                lineResults.Add(new ClaimLineAdjudication(line.Id, allowedAmount));
            }

            // Calculate totals
            TotalAllowedAmount = _claimLines
                .Where(l => l.Status == ClaimLineStatus.Approved)
                .Aggregate(Money.Zero, (sum, line) => sum.Add(line.AllowedAmount));

            TotalPaidAmount = TotalAllowedAmount; // Simplified (could apply copay, deductible)

            // Update claim status
            if (_claimLines.All(l => l.Status == ClaimLineStatus.Approved))
            {
                Status = ClaimStatus.Approved;
                AddDomainEvent(new ClaimApprovedEvent(Id, ClaimNumber, TotalPaidAmount));
            }
            else if (_claimLines.All(l => l.Status == ClaimLineStatus.Denied))
            {
                Status = ClaimStatus.Denied;
                AddDomainEvent(new ClaimDeniedEvent(Id, ClaimNumber,
                    _claimLines.First().DenialReason));
            }
            else
            {
                Status = ClaimStatus.PartiallyApproved;
                AddDomainEvent(new ClaimPartiallyApprovedEvent(Id, ClaimNumber, TotalPaidAmount));
            }

            return new AdjudicationResult(Status, lineResults);
        }

        // Private helper
        private void Deny(DenialReason reason, string explanation)
        {
            Status = ClaimStatus.Denied;
            AddDomainEvent(new ClaimDeniedEvent(Id, ClaimNumber, reason));
        }
    }

    // Entity within Claim aggregate
    public class ClaimLine : Entity<ClaimLineId>
    {
        public ClaimId ClaimId { get; private set; } // Reference to parent
        public ServiceCode ServiceCode { get; private set; }
        public int Units { get; private set; }
        public Money ChargedAmount { get; private set; }
        public Money AllowedAmount { get; private set; }
        public Money PaidAmount { get; private set; }
        public ClaimLineStatus Status { get; private set; }
        public DenialReason? DenialReason { get; private set; }
        public List<DiagnosisCode> DiagnosisCodes { get; private set; }

        // Internal constructor - only Claim aggregate root can create
        internal static ClaimLine Create(
            ClaimLineId id,
            ClaimId claimId,
            ServiceCode serviceCode,
            int units,
            Money chargedAmount,
            List<DiagnosisCode> diagnosisCodes)
        {
            return new ClaimLine
            {
                Id = id,
                ClaimId = claimId,
                ServiceCode = serviceCode,
                Units = units,
                ChargedAmount = chargedAmount,
                DiagnosisCodes = diagnosisCodes,
                Status = ClaimLineStatus.Submitted
            };
        }

        // Internal behavior - only Claim aggregate can modify
        internal void Approve(Money allowedAmount)
        {
            AllowedAmount = allowedAmount;
            PaidAmount = allowedAmount; // Simplified
            Status = ClaimLineStatus.Approved;
        }

        internal void Deny(DenialReason reason)
        {
            DenialReason = reason;
            Status = ClaimLineStatus.Denied;
            AllowedAmount = Money.Zero;
            PaidAmount = Money.Zero;
        }
    }

    // Value Object - used by both Claim and ClaimLine
    public record DiagnosisCode
    {
        public string Code { get; init; }
        public DiagnosisCodeType Type { get; init; } // ICD-10, ICD-9

        public static DiagnosisCode FromIcd10(string code)
        {
            if (string.IsNullOrWhiteSpace(code) || code.Length < 3)
                throw new DomainException("Invalid ICD-10 code");

            return new DiagnosisCode
            {
                Code = code.ToUpper(),
                Type = DiagnosisCodeType.ICD10
            };
        }
    }
}
```

**Key Aggregate Design Decisions:**

1. **Aggregate Boundary**: Claim + ClaimLines (not Claim + Provider + Member)
   - Rationale: ClaimLines must be consistent with Claim totals (invariant)
   - Provider and Member are separate aggregates referenced by ID

2. **Invariants Enforced**:
   - No duplicate service codes on a claim
   - Total claim amount ≤ $50,000
   - At least one diagnosis code per line
   - Can only adjudicate claims in Submitted/Returned status

3. **Internal Constructors**: ClaimLine has internal constructor, only Claim can create
   - Prevents external code from bypassing aggregate rules

4. **Domain Events**: Claim raises events for state changes (Submitted, Approved, Denied)
   - Other bounded contexts can react without tight coupling

**Step 5: Implement Value Objects for Domain Concepts**

Value objects represent descriptive aspects of the domain with no conceptual identity. They are immutable and compared by value, not identity.

```csharp
// Money Value Object - used throughout Claims domain
namespace Gainwell.Claims.Domain.ValueObjects
{
    public record Money
    {
        public decimal Amount { get; init; }
        public string Currency { get; init; }

        // Named constructor
        public static Money FromDollars(decimal amount)
        {
            if (amount < 0)
                throw new DomainException("Money amount cannot be negative");

            return new Money { Amount = amount, Currency = "USD" };
        }

        public static Money Zero => new() { Amount = 0, Currency = "USD" };

        // Domain operations
        public Money Add(Money other)
        {
            if (Currency != other.Currency)
                throw new DomainException("Cannot add money with different currencies");

            return FromDollars(Amount + other.Amount);
        }

        public Money Subtract(Money other)
        {
            if (Currency != other.Currency)
                throw new DomainException("Cannot subtract money with different currencies");

            var result = Amount - other.Amount;
            if (result < 0)
                throw new DomainException("Resulting amount would be negative");

            return FromDollars(result);
        }

        public Money MultiplyBy(decimal factor)
        {
            if (factor < 0)
                throw new DomainException("Cannot multiply by negative factor");

            return FromDollars(Amount * factor);
        }

        public bool IsGreaterThan(Money other) => Amount > other.Amount;
        public bool IsLessThan(Money other) => Amount < other.Amount;

        // Formatting for display
        public override string ToString() => $"${Amount:N2}";
    }

    // ClaimNumber Value Object - enforces format
    public record ClaimNumber
    {
        public string Value { get; init; }

        // Format: STATE-YEAR-SEQUENCE (e.g., "CA-2024-0001234567")
        public static ClaimNumber Create(string stateCode, int year, long sequence)
        {
            if (string.IsNullOrWhiteSpace(stateCode) || stateCode.Length != 2)
                throw new DomainException("State code must be 2 characters");

            if (year < 2000 || year > 2100)
                throw new DomainException("Invalid year");

            if (sequence < 1)
                throw new DomainException("Sequence must be positive");

            var value = $"{stateCode.ToUpper()}-{year}-{sequence:D10}";
            return new ClaimNumber { Value = value };
        }

        public static ClaimNumber Parse(string value)
        {
            if (string.IsNullOrWhiteSpace(value))
                throw new DomainException("Claim number cannot be empty");

            var parts = value.Split('-');
            if (parts.Length != 3)
                throw new DomainException("Invalid claim number format");

            return new ClaimNumber { Value = value };
        }

        public override string ToString() => Value;
    }

    // DateOfService Value Object - enforces business rules
    public record DateOfService
    {
        public DateTime Date { get; init; }

        public static DateOfService FromDate(DateTime date)
        {
            // Business Rule: Service date cannot be in future
            if (date.Date > DateTime.UtcNow.Date)
                throw new DomainException("Service date cannot be in the future");

            // Business Rule: Service date cannot be more than 1 year old
            if (date.Date < DateTime.UtcNow.Date.AddYears(-1))
                throw new DomainException("Service date cannot be more than 1 year old");

            return new DateOfService { Date = date.Date }; // Time component removed
        }

        public bool IsInFuture() => Date > DateTime.UtcNow.Date;
        public bool IsMoreThanOneYearOld() => Date < DateTime.UtcNow.Date.AddYears(-1);

        public override string ToString() => Date.ToString("yyyy-MM-dd");
    }

    // ServiceCode Value Object - references billing code system
    public record ServiceCode
    {
        public string Code { get; init; }
        public ServiceCodeType Type { get; init; } // CPT, HCPCS, ICD Procedure

        public static ServiceCode FromCpt(string code)
        {
            // CPT codes are 5 digits
            if (string.IsNullOrWhiteSpace(code) || !System.Text.RegularExpressions.Regex.IsMatch(code, @"^\d{5}$"))
                throw new DomainException("CPT code must be 5 digits");

            return new ServiceCode { Code = code, Type = ServiceCodeType.CPT };
        }

        public static ServiceCode FromHcpcs(string code)
        {
            // HCPCS codes: 1 letter + 4 digits
            if (string.IsNullOrWhiteSpace(code) || !System.Text.RegularExpressions.Regex.IsMatch(code, @"^[A-Z]\d{4}$"))
                throw new DomainException("HCPCS code must be 1 letter + 4 digits");

            return new ServiceCode { Code = code.ToUpper(), Type = ServiceCodeType.HCPCS };
        }

        public override string ToString() => $"{Type}:{Code}";
    }
}

public enum ServiceCodeType
{
    CPT,      // Current Procedural Terminology
    HCPCS,    // Healthcare Common Procedure Coding System
    ICD       // ICD Procedure codes
}
```

**Value Object Design Patterns:**

1. **Immutability**: All properties are `init`-only, operations return new instances
2. **Self-Validation**: Constructor validates business rules
3. **Named Constructors**: `FromDollars()`, `FromCpt()` clarify intent
4. **Domain Operations**: `Add()`, `Subtract()` for Money, not just properties
5. **Record Types**: C# records provide value equality by default

**Step 6: Implement Domain Events for State Changes**

Domain events capture significant state changes within a bounded context. They enable loose coupling between aggregates and bounded contexts.

```csharp
// Domain Events - Claims Bounded Context
namespace Gainwell.Claims.Domain.Events
{
    // Base domain event
    public abstract record DomainEvent
    {
        public Guid EventId { get; init; } = Guid.NewGuid();
        public DateTime OccurredAt { get; init; } = DateTime.UtcNow;
    }

    // Claim state change events
    public record ClaimSubmittedEvent : DomainEvent
    {
        public ClaimId ClaimId { get; init; }
        public ClaimNumber ClaimNumber { get; init; }
        public ProviderId ProviderId { get; init; }
        public MemberId MemberId { get; init; }
        public DateOfService ServiceDate { get; init; }
        public Money TotalBilledAmount { get; init; }
    }

    public record ClaimApprovedEvent : DomainEvent
    {
        public ClaimId ClaimId { get; init; }
        public ClaimNumber ClaimNumber { get; init; }
        public Money ApprovedAmount { get; init; }
        public string ApprovedBy { get; init; } // User or system
    }

    public record ClaimDeniedEvent : DomainEvent
    {
        public ClaimId ClaimId { get; init; }
        public ClaimNumber ClaimNumber { get; init; }
        public DenialReason Reason { get; init; }
        public string Explanation { get; init; }
    }

    public record ClaimLineAddedEvent : DomainEvent
    {
        public ClaimId ClaimId { get; init; }
        public ClaimLineId LineId { get; init; }
        public ServiceCode ServiceCode { get; init; }
        public Money ChargedAmount { get; init; }
    }
}

// Domain Event Handlers - In-Process
namespace Gainwell.Claims.Domain.EventHandlers
{
    // Handler for ClaimApprovedEvent within Claims context
    public class ClaimApprovedEventHandler : IDomainEventHandler<ClaimApprovedEvent>
    {
        private readonly IProviderStatisticsRepository _providerStats;
        private readonly IAuditLog _auditLog;

        public async Task HandleAsync(ClaimApprovedEvent evt)
        {
            // Update provider statistics (read model)
            var stats = await _providerStats.GetByProviderAsync(evt.ProviderId);
            stats.IncrementApprovedClaims();
            stats.AddToTotalApprovedAmount(evt.ApprovedAmount);
            await _providerStats.SaveAsync(stats);

            // Create audit log entry
            await _auditLog.LogAsync(new AuditEntry
            {
                EntityType = "Claim",
                EntityId = evt.ClaimId.ToString(),
                Action = "Approved",
                Details = $"Claim {evt.ClaimNumber} approved for {evt.ApprovedAmount}",
                Timestamp = evt.OccurredAt
            });
        }
    }
}

// Integration Event Publishing - Cross-Context
namespace Gainwell.Claims.Infrastructure.IntegrationEvents
{
    // Adapter: Domain Event → Integration Event
    public class ClaimApprovedIntegrationEventPublisher
        : IDomainEventHandler<ClaimApprovedEvent>
    {
        private readonly IServiceBus _serviceBus;
        private readonly IClaimRepository _claimRepo;

        public async Task HandleAsync(ClaimApprovedEvent domainEvent)
        {
            // Load full aggregate for integration event
            var claim = await _claimRepo.GetByIdAsync(domainEvent.ClaimId);

            // Create integration event with data other contexts need
            var integrationEvent = new ClaimApprovedIntegrationEvent
            {
                EventId = domainEvent.EventId,
                ClaimNumber = domainEvent.ClaimNumber.Value,
                ProviderId = claim.ProviderId.Value,
                MemberId = claim.MemberId.Value,
                ServiceDate = claim.ServiceDate.Date,
                ApprovedAmount = domainEvent.ApprovedAmount.Amount,
                ApprovedAt = domainEvent.OccurredAt,
                // Flattened claim lines for external consumers
                ClaimLines = claim.ClaimLines.Select(line => new
                {
                    ServiceCode = line.ServiceCode.Code,
                    Units = line.Units,
                    AllowedAmount = line.AllowedAmount.Amount,
                    PaidAmount = line.PaidAmount.Amount
                }).ToList()
            };

            // Publish to Service Bus for other bounded contexts
            await _serviceBus.PublishAsync(integrationEvent, "claims-events");
        }
    }
}
```

**Domain Event Patterns:**

1. **In-Process Events**: Handled synchronously within same bounded context (same transaction)
2. **Integration Events**: Published to message bus for other bounded contexts (eventual consistency)
3. **Event Sourcing (Optional)**: Store domain events as source of truth (not shown, adds complexity)

**Step 7: Implement Repositories with Domain Language**

Repositories provide abstraction over data persistence using domain language, not database language.

```csharp
// Repository Interface - Domain Layer
namespace Gainwell.Claims.Domain.Repositories
{
    // Repository speaks domain language, not database language
    public interface IClaimRepository
    {
        // Aggregate loading
        Task<Claim> GetByIdAsync(ClaimId claimId);
        Task<Claim> GetByClaimNumberAsync(ClaimNumber claimNumber);

        // Domain queries (not "SELECT * WHERE...")
        Task<List<Claim>> GetPendingClaimsForProviderAsync(
            ProviderId providerId,
            DateRange dateRange);

        Task<List<Claim>> GetClaimsRequiringReviewAsync(Money thresholdAmount);

        Task<List<Claim>> GetDeniedClaimsForMemberAsync(
            MemberId memberId,
            DateTime since);

        // Aggregate persistence
        Task SaveAsync(Claim claim);
        Task DeleteAsync(ClaimId claimId); // Rarely used in healthcare (audit requirements)

        // Domain-specific queries
        Task<bool> HasDuplicateClaimAsync(
            ClaimNumber claimNumber,
            ProviderId providerId,
            DateOfService serviceDate);

        Task<Money> GetTotalPaidAmountForProviderAsync(
            ProviderId providerId,
            DateRange dateRange);
    }
}

// Repository Implementation - Infrastructure Layer
namespace Gainwell.Claims.Infrastructure.Persistence
{
    public class ClaimRepository : IClaimRepository
    {
        private readonly ClaimsDbContext _dbContext;
        private readonly IDomainEventDispatcher _eventDispatcher;

        public async Task<Claim> GetByIdAsync(ClaimId claimId)
        {
            // Load aggregate root with all child entities
            var claimEntity = await _dbContext.Claims
                .Include(c => c.ClaimLines)
                    .ThenInclude(l => l.DiagnosisCodes)
                .Include(c => c.Adjustments)
                .FirstOrDefaultAsync(c => c.Id == claimId.Value);

            if (claimEntity == null)
                return null;

            // Map database entity to domain aggregate
            return ClaimMapper.ToDomain(claimEntity);
        }

        public async Task<Claim> GetByClaimNumberAsync(ClaimNumber claimNumber)
        {
            var claimEntity = await _dbContext.Claims
                .Include(c => c.ClaimLines)
                    .ThenInclude(l => l.DiagnosisCodes)
                .FirstOrDefaultAsync(c => c.ClaimNumber == claimNumber.Value);

            return claimEntity == null ? null : ClaimMapper.ToDomain(claimEntity);
        }

        public async Task<List<Claim>> GetPendingClaimsForProviderAsync(
            ProviderId providerId,
            DateRange dateRange)
        {
            var claimEntities = await _dbContext.Claims
                .Include(c => c.ClaimLines)
                .Where(c => c.ProviderId == providerId.Value
                         && c.Status == ClaimStatus.Submitted
                         && c.ServiceDate >= dateRange.Start
                         && c.ServiceDate <= dateRange.End)
                .ToListAsync();

            return claimEntities.Select(ClaimMapper.ToDomain).ToList();
        }

        public async Task SaveAsync(Claim claim)
        {
            // Map domain aggregate to database entity
            var claimEntity = ClaimMapper.ToEntity(claim);

            // Detect new vs existing
            var existingEntity = await _dbContext.Claims
                .FirstOrDefaultAsync(c => c.Id == claim.Id.Value);

            if (existingEntity == null)
            {
                _dbContext.Claims.Add(claimEntity);
            }
            else
            {
                _dbContext.Entry(existingEntity).CurrentValues.SetValues(claimEntity);

                // Handle child entities (ClaimLines)
                _dbContext.ClaimLines.RemoveRange(
                    existingEntity.ClaimLines.Where(existing =>
                        !claimEntity.ClaimLines.Any(current => current.Id == existing.Id)));

                foreach (var line in claimEntity.ClaimLines)
                {
                    var existingLine = existingEntity.ClaimLines
                        .FirstOrDefault(l => l.Id == line.Id);

                    if (existingLine == null)
                        existingEntity.ClaimLines.Add(line);
                    else
                        _dbContext.Entry(existingLine).CurrentValues.SetValues(line);
                }
            }

            // Persist to database
            await _dbContext.SaveChangesAsync();

            // Dispatch domain events after successful persistence
            foreach (var domainEvent in claim.DomainEvents)
            {
                await _eventDispatcher.DispatchAsync(domainEvent);
            }

            claim.ClearDomainEvents();
        }

        public async Task<bool> HasDuplicateClaimAsync(
            ClaimNumber claimNumber,
            ProviderId providerId,
            DateOfService serviceDate)
        {
            return await _dbContext.Claims
                .AnyAsync(c => c.ClaimNumber == claimNumber.Value
                            && c.ProviderId == providerId.Value
                            && c.ServiceDate == serviceDate.Date
                            && c.Status != ClaimStatus.Voided);
        }

        public async Task<Money> GetTotalPaidAmountForProviderAsync(
            ProviderId providerId,
            DateRange dateRange)
        {
            var total = await _dbContext.Claims
                .Where(c => c.ProviderId == providerId.Value
                         && c.ServiceDate >= dateRange.Start
                         && c.ServiceDate <= dateRange.End
                         && c.Status == ClaimStatus.Approved)
                .SumAsync(c => c.TotalPaidAmount);

            return Money.FromDollars(total);
        }
    }
}
```

**Repository Design Principles:**

1. **Domain Language**: Method names use domain terms (GetPendingClaimsForProvider, not GetWhereStatusEquals)
2. **Aggregate Loading**: Always load complete aggregate with child entities
3. **Transactional Consistency**: Save aggregate and dispatch events in same transaction
4. **Mapping Layer**: Separate domain models from database entities (persistence ignorance)

