### 4.2 Testing Strategy for DDD

**Aggregate Unit Tests:**

```csharp
// Test Claim aggregate invariants
public class ClaimAggregateTests
{
    [Fact]
    public void SubmitClaim_WithValidData_CreatesClaimWithSubmittedStatus()
    {
        // Arrange
        var claimNumber = ClaimNumber.Create("CA", 2024, 1234567);
        var providerId = ProviderId.New();
        var memberId = MemberId.New();
        var serviceDate = DateOfService.FromDate(DateTime.UtcNow.AddDays(-10));
        var lineData = new List<ClaimLineData>
        {
            new ClaimLineData
            {
                ServiceCode = ServiceCode.FromCpt("99213"),
                Units = 1,
                ChargedAmount = Money.FromDollars(150.00m),
                DiagnosisCodes = new List<DiagnosisCode> { DiagnosisCode.FromIcd10("E11.9") }
            }
        };

        // Act
        var claim = Claim.Submit(claimNumber, providerId, memberId, serviceDate, lineData);

        // Assert
        Assert.Equal(ClaimStatus.Submitted, claim.Status);
        Assert.Single(claim.ClaimLines);
        Assert.Equal(Money.FromDollars(150.00m), claim.TotalBilledAmount);
        Assert.Contains(claim.DomainEvents, e => e is ClaimSubmittedEvent);
    }

    [Fact]
    public void AddClaimLine_WithDuplicateServiceCode_ThrowsDomainException()
    {
        // Arrange
        var claim = CreateValidClaim();
        var serviceCode = ServiceCode.FromCpt("99213");
        claim.AddClaimLine(serviceCode, 1, Money.FromDollars(150m),
            new List<DiagnosisCode> { DiagnosisCode.FromIcd10("E11.9") });

        // Act & Assert
        var exception = Assert.Throws<DomainException>(() =>
            claim.AddClaimLine(serviceCode, 1, Money.FromDollars(150m),
                new List<DiagnosisCode> { DiagnosisCode.FromIcd10("E11.9") }));

        Assert.Contains("already contains service", exception.Message);
    }

    [Fact]
    public void Adjudicate_WithIneligibleMember_DeniesClaim()
    {
        // Arrange
        var claim = CreateValidClaim();
        var eligibility = MemberEligibility.Inactive(claim.MemberId, claim.ServiceDate);
        var credential = ProviderCredential.Valid(claim.ProviderId);
        var pricing = FeeSchedule.Standard();
        var authPolicy = PriorAuthorizationPolicy.NoAuthRequired();

        // Act
        var result = claim.Adjudicate(eligibility, credential, pricing, authPolicy);

        // Assert
        Assert.Equal(AdjudicationStatus.Denied, result.Status);
        Assert.Equal(DenialReason.MemberNotEligible, result.DenialReason);
        Assert.Equal(ClaimStatus.Denied, claim.Status);
        Assert.Contains(claim.DomainEvents, e => e is ClaimDeniedEvent);
    }
}
```

