### Example 2: Provider Credentialing Bounded Context

This example shows how Provider Management bounded context handles provider credentialing workflows with complex state machines and regulatory requirements.

**Business Context:**

Gainwell manages 400,000+ healthcare providers across 50+ state Medicaid programs. Each provider must be credentialed (verified licenses, malpractice insurance, board certifications) before billing claims. Credentialing involves 15-step workflow with 30-90 day processing time and strict regulatory requirements.

**Domain Model:**

```csharp
// Provider aggregate root
public class Provider : AggregateRoot<ProviderId>
{
    private readonly List<Credential> _credentials = new();
    private readonly List<Network> _networks = new();

    public NationalProviderIdentifier Npi { get; private set; }
    public ProviderName Name { get; private set; }
    public ProviderType Type { get; private set; } // Individual, Group, Facility
    public ProviderStatus Status { get; private set; }
    public DateOfEnrollment EnrollmentDate { get; private set; }

    public IReadOnlyList<Credential> Credentials => _credentials.AsReadOnly();
    public IReadOnlyList<Network> Networks => _networks.AsReadOnly();

    // Factory method
    public static Provider Enroll(
        NationalProviderIdentifier npi,
        ProviderName name,
        ProviderType type,
        TaxIdentificationNumber tin,
        List<SpecialtyCode> specialties)
    {
        // Business rules enforced
        if (specialties == null || !specialties.Any())
            throw new DomainException("Provider must have at least one specialty");

        var provider = new Provider
        {
            Id = ProviderId.New(),
            Npi = npi,
            Name = name,
            Type = type,
            Status = ProviderStatus.PendingCredentialing,
            EnrollmentDate = DateOfEnrollment.Today()
        };

        provider.AddDomainEvent(new ProviderEnrolledEvent(provider.Id, provider.Npi, provider.Name));

        return provider;
    }

    // Business behavior - credential provider
    public CredentialingResult StartCredentialing(
        MedicalLicense license,
        MalpracticeInsurance insurance,
        List<BoardCertification> certifications)
    {
        // Invariant: Can only credential providers in PendingCredentialing status
        if (Status != ProviderStatus.PendingCredentialing && Status != ProviderStatus.RecredentialingRequired)
            throw new DomainException($"Cannot credential provider in {Status} status");

        // Invariant: Medical license must be active
        if (license.IsExpired())
            return CredentialingResult.Failed("Medical license expired");

        // Invariant: Malpractice insurance must meet state minimums
        if (!insurance.MeetsStateMinimum())
            return CredentialingResult.Failed("Malpractice insurance below state minimum");

        // Create credential aggregate
        var credential = Credential.Create(
            CredentialId.New(),
            Id,
            license,
            insurance,
            certifications);

        _credentials.Add(credential);
        Status = ProviderStatus.UnderReview;

        AddDomainEvent(new ProviderCredentialingStartedEvent(Id, Npi, credential.Id));

        return CredentialingResult.Success(credential.Id);
    }

    // Business behavior - approve credentialing
    public void ApproveCredentialing(CredentialId credentialId, CredentialingReviewer reviewer)
    {
        var credential = _credentials.FirstOrDefault(c => c.Id == credentialId);
        if (credential == null)
            throw new DomainException("Credential not found");

        // Invariant: Credential must be under review
        if (credential.Status != CredentialStatus.UnderReview)
            throw new DomainException($"Cannot approve credential in {credential.Status} status");

        // Approve credential (state transition)
        credential.Approve(reviewer, DateTime.UtcNow);

        // Update provider status
        Status = ProviderStatus.Active;

        AddDomainEvent(new ProviderCredentialedEvent(Id, Npi, credentialId));
    }

    // Business behavior - suspend provider
    public void Suspend(SuspensionReason reason, string explanation)
    {
        // Invariant: Can only suspend active providers
        if (Status != ProviderStatus.Active)
            throw new DomainException($"Cannot suspend provider in {Status} status");

        Status = ProviderStatus.Suspended;

        AddDomainEvent(new ProviderSuspendedEvent(Id, Npi, reason, explanation, DateTime.UtcNow));
    }

    // Business query - is provider eligible to bill?
    public bool CanBillOnDate(DateTime serviceDate)
    {
        if (Status != ProviderStatus.Active)
            return false;

        // Check active credential on service date
        var activeCredential = _credentials
            .FirstOrDefault(c => c.IsValidOn(serviceDate));

        return activeCredential != null;
    }
}

// Credential entity within Provider aggregate
public class Credential : Entity<CredentialId>
{
    public ProviderId ProviderId { get; private set; }
    public MedicalLicense License { get; private set; }
    public MalpracticeInsurance Insurance { get; private set; }
    public List<BoardCertification> Certifications { get; private set; }
    public CredentialStatus Status { get; private set; }
    public DateTime? ApprovedDate { get; private set; }
    public DateTime? ExpirationDate { get; private set; }
    public CredentialingReviewer ApprovedBy { get; private set; }

    internal static Credential Create(
        CredentialId id,
        ProviderId providerId,
        MedicalLicense license,
        MalpracticeInsurance insurance,
        List<BoardCertification> certifications)
    {
        return new Credential
        {
            Id = id,
            ProviderId = providerId,
            License = license,
            Insurance = insurance,
            Certifications = certifications ?? new List<BoardCertification>(),
            Status = CredentialStatus.UnderReview
        };
    }

    internal void Approve(CredentialingReviewer reviewer, DateTime approvedDate)
    {
        Status = CredentialStatus.Approved;
        ApprovedDate = approvedDate;
        ApprovedBy = reviewer;

        // Credential valid for 3 years
        ExpirationDate = approvedDate.AddYears(3);
    }

    public bool IsValidOn(DateTime date)
    {
        return Status == CredentialStatus.Approved
            && ApprovedDate.HasValue
            && ApprovedDate.Value <= date
            && (ExpirationDate == null || ExpirationDate.Value >= date);
    }
}
```

**Integration with Claims Context:**

```csharp
// Claims context subscribes to Provider events
public class ProviderSuspendedIntegrationEventHandler
    : IIntegrationEventHandler<ProviderSuspendedIntegrationEvent>
{
    private readonly IClaimRepository _claimRepo;

    public async Task HandleAsync(ProviderSuspendedIntegrationEvent evt)
    {
        // Find pending claims for suspended provider
        var pendingClaims = await _claimRepo.GetPendingClaimsForProviderAsync(
            ProviderId.From(evt.ProviderId),
            new DateRange(evt.SuspendedAt, DateTime.UtcNow));

        // Deny all pending claims
        foreach (var claim in pendingClaims)
        {
            claim.Deny(DenialReason.ProviderSuspended,
                $"Provider suspended: {evt.Reason}");
        }

        await _claimRepo.SaveManyAsync(pendingClaims);
    }
}
```

**Benefits:**

1. **Regulatory Compliance**: Credentialing workflow encapsulated in Provider aggregate ensures all regulatory steps followed
2. **State Machine**: Provider status transitions (PendingCredentialing → UnderReview → Active → Suspended) enforced by aggregate invariants
3. **Cross-Context Integration**: Claims context reacts to ProviderSuspendedEvent without direct coupling to Provider context
4. **Domain Expertise**: Provider team owns credentialing logic (not shared with Claims team)

