### Example 3: Member Eligibility Verification

This example demonstrates how Member bounded context handles complex eligibility verification with multiple coverage types, benefit limits, and eligibility spans.

**Business Context:**

Gainwell manages eligibility for 72+ million Medicaid enrollees. Members can have multiple eligibility spans (periods of coverage), different benefit plans, and complex eligibility rules based on age, income, and household composition.

**Domain Model:**

```csharp
// Member aggregate root
public class Member : AggregateRoot<MemberId>
{
    private readonly List<EligibilitySpan> _eligibilitySpans = new();
    private readonly List<BenefitPlan> _benefitPlans = new();

    public MemberIdentifier MemberIdentifier { get; private set; }
    public MemberName Name { get; private set; }
    public DateOfBirth DateOfBirth { get; private set; }
    public MemberStatus Status { get; private set; }

    public IReadOnlyList<EligibilitySpan> EligibilitySpans => _eligibilitySpans.AsReadOnly();
    public IReadOnlyList<BenefitPlan> BenefitPlans => _benefitPlans.AsReadOnly();

    // Factory method
    public static Member Enroll(
        MemberIdentifier memberIdentifier,
        MemberName name,
        DateOfBirth dateOfBirth,
        EligibilityCriteria criteria)
    {
        // Business rules
        if (dateOfBirth.IsInFuture())
            throw new DomainException("Date of birth cannot be in future");

        var member = new Member
        {
            Id = MemberId.New(),
            MemberIdentifier = memberIdentifier,
            Name = name,
            DateOfBirth = dateOfBirth,
            Status = MemberStatus.PendingVerification
        };

        member.AddDomainEvent(new MemberEnrolledEvent(member.Id, member.MemberIdentifier));

        return member;
    }

    // Business behavior - add eligibility span
    public void AddEligibilitySpan(
        DateTime effectiveDate,
        DateTime? terminationDate,
        BenefitPlanCode planCode,
        EligibilityCategory category)
    {
        // Invariant: No overlapping eligibility spans
        var overlapping = _eligibilitySpans
            .Any(span => span.OverlapsWith(effectiveDate, terminationDate));

        if (overlapping)
            throw new DomainException("Eligibility spans cannot overlap");

        // Create eligibility span
        var span = EligibilitySpan.Create(
            EligibilitySpanId.New(),
            Id,
            effectiveDate,
            terminationDate,
            planCode,
            category);

        _eligibilitySpans.Add(span);
        Status = MemberStatus.Active;

        AddDomainEvent(new EligibilitySpanAddedEvent(Id, span.Id, effectiveDate, terminationDate));
    }

    // Business query - is member eligible on date?
    public EligibilityVerificationResult VerifyEligibilityOn(DateTime serviceDate)
    {
        // Find active eligibility span on service date
        var activeSpan = _eligibilitySpans
            .FirstOrDefault(span => span.IsActiveOn(serviceDate));

        if (activeSpan == null)
            return EligibilityVerificationResult.NotEligible("No active coverage on service date");

        // Get benefit plan for span
        var benefitPlan = _benefitPlans
            .FirstOrDefault(plan => plan.PlanCode == activeSpan.PlanCode);

        if (benefitPlan == null)
            return EligibilityVerificationResult.NotEligible("Benefit plan not found");

        return EligibilityVerificationResult.Eligible(
            activeSpan,
            benefitPlan,
            CalculateAgeOn(serviceDate));
    }

    // Business query - check service coverage
    public ServiceCoverageResult CheckServiceCoverage(
        DateTime serviceDate,
        ServiceCode serviceCode)
    {
        var eligibility = VerifyEligibilityOn(serviceDate);
        if (!eligibility.IsEligible)
            return ServiceCoverageResult.NotCovered(eligibility.Reason);

        // Check if service is covered by benefit plan
        var isCovered = eligibility.BenefitPlan.CoversService(
            serviceCode,
            CalculateAgeOn(serviceDate));

        if (!isCovered)
            return ServiceCoverageResult.NotCovered("Service not covered by benefit plan");

        // Check benefit limits
        var hasRemainingBenefits = eligibility.BenefitPlan.HasRemainingBenefits(
            serviceCode,
            serviceDate);

        if (!hasRemainingBenefits)
            return ServiceCoverageResult.LimitExceeded("Benefit limit exceeded for service");

        return ServiceCoverageResult.Covered(
            eligibility.BenefitPlan,
            eligibility.EligibilitySpan);
    }

    private int CalculateAgeOn(DateTime date)
    {
        var age = date.Year - DateOfBirth.Value.Year;
        if (date.Month < DateOfBirth.Value.Month ||
            (date.Month == DateOfBirth.Value.Month && date.Day < DateOfBirth.Value.Day))
        {
            age--;
        }
        return age;
    }
}

// EligibilitySpan entity within Member aggregate
public class EligibilitySpan : Entity<EligibilitySpanId>
{
    public MemberId MemberId { get; private set; }
    public DateTime EffectiveDate { get; private set; }
    public DateTime? TerminationDate { get; private set; }
    public BenefitPlanCode PlanCode { get; private set; }
    public EligibilityCategory Category { get; private set; }

    internal static EligibilitySpan Create(
        EligibilitySpanId id,
        MemberId memberId,
        DateTime effectiveDate,
        DateTime? terminationDate,
        BenefitPlanCode planCode,
        EligibilityCategory category)
    {
        return new EligibilitySpan
        {
            Id = id,
            MemberId = memberId,
            EffectiveDate = effectiveDate,
            TerminationDate = terminationDate,
            PlanCode = planCode,
            Category = category
        };
    }

    public bool IsActiveOn(DateTime date)
    {
        return date >= EffectiveDate &&
               (TerminationDate == null || date <= TerminationDate.Value);
    }

    public bool OverlapsWith(DateTime effectiveDate, DateTime? terminationDate)
    {
        // Check if date ranges overlap
        if (terminationDate == null || TerminationDate == null)
            return effectiveDate <= (TerminationDate ?? DateTime.MaxValue);

        return effectiveDate <= TerminationDate.Value &&
               terminationDate.Value >= EffectiveDate;
    }
}
```

**Benefits:**

1. **Complex Business Rules**: Eligibility verification encapsulated in Member aggregate
2. **Invariant Protection**: No overlapping eligibility spans enforced at aggregate level
3. **Rich Queries**: Domain methods like `VerifyEligibilityOn()` and `CheckServiceCoverage()` use ubiquitous language
4. **Age-Based Rules**: Member calculates age on service date for age-dependent coverage rules

