### Example 4: Cross-Context Saga - Claim Approval Workflow

This example shows how multiple bounded contexts coordinate through events to complete a claim approval workflow without tight coupling.

**Workflow:**

1. Claims context approves claim
2. Payment context schedules payment
3. Provider context updates provider statistics
4. Analytics context updates reporting metrics

**Implementation:**

```csharp
// Step 1: Claims context approves claim
public class Claim : AggregateRoot<ClaimId>
{
    public void Approve(Money approvedAmount, string approvedBy)
    {
        Status = ClaimStatus.Approved;
        ApprovedAmount = approvedAmount;
        ApprovedBy = approvedBy;
        ApprovedDate = DateTime.UtcNow;

        // Raise domain event (in-process)
        AddDomainEvent(new ClaimApprovedEvent(Id, ClaimNumber, approvedAmount));
    }
}

// Domain event handler publishes integration event
public class ClaimApprovedIntegrationEventPublisher
    : IDomainEventHandler<ClaimApprovedEvent>
{
    private readonly IServiceBus _serviceBus;

    public async Task HandleAsync(ClaimApprovedEvent domainEvent)
    {
        // Translate domain event to integration event
        var integrationEvent = new ClaimApprovedIntegrationEvent
        {
            EventId = domainEvent.EventId,
            ClaimNumber = domainEvent.ClaimNumber.Value,
            ApprovedAmount = domainEvent.ApprovedAmount.Amount,
            ApprovedAt = domainEvent.OccurredAt
        };

        // Publish to Service Bus
        await _serviceBus.PublishAsync(integrationEvent, "claims-events");
    }
}

// Step 2: Payment context schedules payment
public class ClaimApprovedPaymentHandler
    : IIntegrationEventHandler<ClaimApprovedIntegrationEvent>
{
    private readonly IPaymentRepository _paymentRepo;

    public async Task HandleAsync(ClaimApprovedIntegrationEvent evt)
    {
        // Create Payment aggregate
        var payment = Payment.Schedule(
            PaymentNumber.Generate(),
            ClaimNumber.Parse(evt.ClaimNumber),
            ProviderId.From(evt.ProviderId),
            Money.FromDollars(evt.ApprovedAmount),
            PaymentCycle.NextCycle());

        await _paymentRepo.SaveAsync(payment);
    }
}

// Step 3: Provider context updates statistics
public class ClaimApprovedProviderStatsHandler
    : IIntegrationEventHandler<ClaimApprovedIntegrationEvent>
{
    private readonly IProviderStatisticsRepository _statsRepo;

    public async Task HandleAsync(ClaimApprovedIntegrationEvent evt)
    {
        var stats = await _statsRepo.GetByProviderAsync(evt.ProviderId);
        stats.IncrementApprovedClaims();
        stats.AddToTotalApprovedAmount(Money.FromDollars(evt.ApprovedAmount));
        await _statsRepo.SaveAsync(stats);
    }
}

// Step 4: Analytics context updates metrics
public class ClaimApprovedAnalyticsHandler
    : IIntegrationEventHandler<ClaimApprovedIntegrationEvent>
{
    private readonly IClaimMetricsRepository _metricsRepo;

    public async Task HandleAsync(ClaimApprovedIntegrationEvent evt)
    {
        var metrics = await _metricsRepo.GetForDate(evt.ApprovedAt.Date);
        metrics.IncrementApprovedClaimsCount();
        metrics.AddToTotalApprovedAmount(evt.ApprovedAmount);
        await _metricsRepo.SaveAsync(metrics);
    }
}
```

**Benefits:**

1. **Loose Coupling**: Claims context doesn't know about Payment, Provider, or Analytics contexts
2. **Eventual Consistency**: Payment scheduled asynchronously (within 5 seconds)
3. **Resilience**: If Payment context fails, Claims approval still succeeds (payment retried later)
4. **Independent Evolution**: Each context can change its implementation without affecting others

